#!/usr/bin/env python3
"""PreToolUse guard (Write|Edit|MultiEdit): generated files are never hand-edited.

Reads the hook payload from stdin, finds the target path, and refuses (exit 2, reason on
stderr) when the file is marked as generated by scripts/kernel/sync.py, sweep.py or another agency script. A user-scope
plugin fires this hook in every folder, so outside the agency's own folders (the code repo, the data folder, the
runtime folder) only a marker that names an agency script (`GENERATED by scripts/<name>.py`, `hooks/<name>.py`) counts:
a generated file in an unrelated project (`GENERATED by protoc`) is not ours.

Where the marker lives (written by sync.py, see sync.is_generated):
  - plain text / markdown without frontmatter / toml / yaml / scripts: line 1 (after a shebang)
  - markdown with YAML frontmatter (agents, SKILL.md): a YAML comment on line 2
  - JSON: a top-level "_generated" key
So the guard reads the first 5 lines and, for .json files, the parsed "_generated" key.

Agency scripts write their own generated files with the same header naming themselves, e.g.
"<!-- GENERATED by scripts/role_hub.py from ... - do not edit -->" (DASHBOARD.md, the role hubs): any
"GENERATED by <path>.py" marker in those lines is refused too.

Principle 1: one source of truth per thing. Fails open on any parse error so a broken hook
never blocks ordinary work.
"""
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "scripts"))
import agency_paths as _ap  # noqa: E402

MARKERS = ("GENERATED by ",)                       # sync.py, sweep.py and the record scripts all start their output so
SCRIPT_MARK = re.compile(r"GENERATED by [\w./-]+\.py\b")
AGENCY_MARK = re.compile(r"GENERATED by (?:scripts|hooks)/[\w./-]+\.py\b")      # a marker that names an agency script


def is_generated(path: str, agency_only: bool = False) -> str | None:
    """Return a short reason string if the file is generated, else None. `agency_only`: count only a marker that names an
    agency script (for a file outside the agency's folders)."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            head = [fh.readline() for _ in range(5)]
    except OSError:
        return None  # new file or unreadable: not generated
    for line in head:
        if AGENCY_MARK.search(line) if agency_only else (any(m in line for m in MARKERS) or SCRIPT_MARK.search(line)):
            return line.strip()[:100]
    if path.endswith(".json") and not agency_only:
        try:
            with open(path, "r", encoding="utf-8") as fh:
                data = json.load(fh)
            if isinstance(data, dict) and data.get("_generated"):
                return f'"_generated": {str(data["_generated"])[:80]}'
        except Exception:
            return None
    return None


def in_agency_folders(path: str) -> bool:
    """True when `path` is inside the code repo, the data folder or the runtime folder."""
    try:
        target = Path(path).expanduser().resolve()
        for base in (_ap.CODE_ROOT, _ap.DATA_ROOT, _ap.RUNTIME_ROOT):
            if base.exists() and (target == base.resolve() or base.resolve() in target.parents):
                return True
    except Exception:
        return False
    return False


def main() -> int:
    try:
        payload = json.load(sys.stdin)
    except Exception:
        return 0
    if not isinstance(payload, dict):
        return 0
    tool_input = payload.get("tool_input") or {}
    path = tool_input.get("file_path") or tool_input.get("path") or ""
    if not path:
        return 0
    reason = is_generated(path, agency_only=not in_agency_folders(path))
    if reason:
        sys.stderr.write(
            f"BLOCKED: {path} is generated ({reason}). "
            "Edit the source it names, then run: python3 scripts/kernel/sync.py "
            "(or the script the marker names).\n"
        )
        return 2
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)        # fail-open: a broken guard must never block ordinary work
